-lg px-3 py-2.5 text-rose-400">×</button></div>@endforeach</div>@if($errors->any())<p class="mt-3 text-sm text-rose-400">{{ $errors->first() }}</p>@endif<div class="mt-5 flex justify-end"><button class="rounded-xl bg-emerald-500 px-6 py-3 font-semibold text-slate-950">Zapisz wszystkie kontenery</button></div></form>
