<script>document.addEventListener('DOMContentLoaded',()=>{const r=document.querySelector('#container-rows'),a=document.querySelector('#add-container-row');const b=()=>r.querySelectorAll('.remove-container-row').forEach(x=>x.onclick=()=>{if(r.children.length>1)x.closest('.container-row').remove()});a.onclick=()=>{const c=r.querySelector('.container-row').cloneNode(true),i=Date.now();c.querySelectorAll('[data-field]').forEach(x=>{x.name='containers['+i+']['+x.dataset.field+']';x.value=''});r.appendChild(c);b()};b()});</script></x-warehouse-shell>
